import{_ as d,C as i,o as l,c as a,j as t,a as o,E as c,a2 as r}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"Font Config & Test Screen Widgets (dev.anvilcraft.lib.v2.font.screen)","description":"","frontmatter":{},"headers":[],"relativePath":"en/26.3/font/screens.md","filePath":"en/26.3/font/screens.md"}'),s={name:"en/26.3/font/screens.md"};function g(f,e,p,h,u,b){const n=i("BranchContextCard");return l(),a("div",null,[e[0]||(e[0]=t("h1",{id:"font-config-test-screen-widgets-dev-anvilcraft-lib-v2-font-screen",tabindex:"-1"},[o("Font Config & Test Screen Widgets ("),t("code",null,"dev.anvilcraft.lib.v2.font.screen"),o(") "),t("a",{class:"header-anchor",href:"#font-config-test-screen-widgets-dev-anvilcraft-lib-v2-font-screen","aria-label":'Permalink to "Font Config & Test Screen Widgets (`dev.anvilcraft.lib.v2.font.screen`)"'},"​")],-1)),c(n,{branch:"26.3"}),e[1]||(e[1]=r('<p>The <code>dev.anvilcraft.lib.v2.font.screen</code> and <code>dev.anvilcraft.lib.v2.font.data</code> packages provide <code>anvillib_font</code>&#39;s built-in client font selection screen (<code>FontConfigScreen</code>), multi-style render test page (<code>FontTestScreen</code>), scroll-capable dropdown widget with occlusion shielding (<code>Dropdown</code>), and UI language data generator (<code>AnvilLibFontData</code>).</p><p>These classes are marked <code>@ApiStatus.Internal</code>; players can select <code>AnvilLib Font</code> in NeoForge&#39;s Mods menu and click &quot;Config&quot; to switch the global SDF rendering font.</p><hr><h2 id="_1-screen-widget-structure-interaction-flow" tabindex="-1">1. Screen Widget Structure &amp; Interaction Flow <a class="header-anchor" href="#_1-screen-widget-structure-interaction-flow" aria-label="Permalink to &quot;1. Screen Widget Structure &amp; Interaction Flow&quot;">​</a></h2><ol><li><strong><code>FontConfigScreen</code> (Main Font Config Screen)</strong>: <ul><li>The top bar renders the currently selected font family and weight name live via <code>guiGraphics.anvillib$centeredText(AnvilLibFont.getSelectFont(), ...)</code>;</li><li>Provides two linked <code>Dropdown</code> widgets: selecting a &quot;Font Family&quot; in the upper dropdown calls <code>FontManager.INSTANCE.getFamilyFontNames(family)</code> to refresh the lower &quot;Font&quot; dropdown&#39;s options, and immediately writes to <code>AnvilLibFont.CONFIG.setFontFamily</code> / <code>setFont</code> (<code>config/anvillib/anvillib_font-client.json</code>);</li><li>Clicking the <code>Font Test</code> button at the top opens <code>FontTestScreen</code>.</li></ul></li><li><strong><code>FontTestScreen</code> (Multi-Language &amp; Multi-Style Test Page)</strong>: <ul><li>Uses the selected SDF font to display 10 lines of test text covering Simplified Chinese, Traditional Chinese, English, Japanese kana, digits, and punctuation, verifying red/green/dark-purple colors, <code>withBold</code>, <code>withItalic</code>, bold-italic, <code>withUnderlined</code>, <code>withStrikethrough</code>, and dynamic <code>withObfuscated</code> rendering.</li></ul></li><li><strong><code>Dropdown</code> (Scrollable Dropdown with Occlusion Shielding)</strong>: <ul><li>When multiple <code>Dropdown</code>s are stacked vertically, an expanded upper dropdown overlaps lower ones. <code>Dropdown</code> uses <code>Dropdown.Shielding(x1, y1, x2, y2, dropdown)</code> to notify the parent screen: while expanded, any other <code>Dropdown</code> occluded by its menu rectangle returns <code>false</code> in <code>isMouseOver</code>, preventing click-through onto underlying widgets.</li></ul></li></ol><hr><h2 id="_2-class-api-summary-apistatus-internal" tabindex="-1">2. Class &amp; API Summary (<code>@ApiStatus.Internal</code>) <a class="header-anchor" href="#_2-class-api-summary-apistatus-internal" aria-label="Permalink to &quot;2. Class &amp; API Summary (`@ApiStatus.Internal`)&quot;">​</a></h2><h3 id="_1-fontconfigscreen-fonttestscreen" tabindex="-1">1. <code>FontConfigScreen</code> &amp; <code>FontTestScreen</code> <a class="header-anchor" href="#_1-fontconfigscreen-fonttestscreen" aria-label="Permalink to &quot;1. `FontConfigScreen` &amp; `FontTestScreen`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Class</th><th style="text-align:left;">Constructor &amp; Core Methods</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>FontConfigScreen</code></td><td style="text-align:left;"><code>public FontConfigScreen(final ModContainer ignored, final Screen parent)</code></td><td style="text-align:left;">Registered on <code>ModContainer</code> by <code>AnvilLibFont</code> via <code>IConfigScreenFactory</code>. Manages the font family dropdown, specific font dropdown, and test screen button.</td></tr><tr><td style="text-align:left;"><code>FontTestScreen</code></td><td style="text-align:left;"><code>protected FontTestScreen(final Screen parent)</code></td><td style="text-align:left;">Renders 10 lines of SDF test text with different <code>Style</code> combinations across CJK, English, and symbols; pressing <code>ESC</code> returns to <code>FontConfigScreen</code>.</td></tr></tbody></table><h3 id="_2-dropdown-dev-anvilcraft-lib-v2-font-screen-widget-dropdown" tabindex="-1">2. <code>Dropdown</code> (<code>dev.anvilcraft.lib.v2.font.screen.widget.Dropdown</code>) <a class="header-anchor" href="#_2-dropdown-dev-anvilcraft-lib-v2-font-screen-widget-dropdown" aria-label="Permalink to &quot;2. `Dropdown` (`dev.anvilcraft.lib.v2.font.screen.widget.Dropdown`)&quot;">​</a></h3><p>Extends <code>net.minecraft.client.gui.components.AbstractWidget</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Constructor / Method / Inner Record Signature</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public Dropdown(int x, int y, int width, int height, int screenWidth, int screenHeight, Component message)</code></td><td style="text-align:left;">Constructs a dropdown widget, taking screen dimensions to compute maximum available expanded height.</td></tr><tr><td style="text-align:left;"><code>public void setAllow(List&lt;DropdownEntry&gt; allows)</code></td><td style="text-align:left;">Sets candidate entries and resets <code>scrollOffset = 0</code>; if the previous selection is absent from the new list, selects the first item (or <code>null</code> if empty).</td></tr><tr><td style="text-align:left;"><code>public void setValue(@Nullable DropdownEntry value)</code> / <code>setValue(@Nullable String value)</code></td><td style="text-align:left;">Sets the selected item by <code>DropdownEntry</code> or string <code>id</code> (does not fire <code>onValueChanged</code>).</td></tr><tr><td style="text-align:left;"><code>public @Nullable DropdownEntry getValue()</code> / <code>public @Nullable String getValueId()</code></td><td style="text-align:left;">Returns the currently selected <code>DropdownEntry</code> or its string <code>id</code>.</td></tr><tr><td style="text-align:left;"><code>public void setOnValueChanged(Consumer&lt;@Nullable DropdownEntry&gt; callback)</code></td><td style="text-align:left;">Sets the callback invoked when the user clicks to change the selected option.</td></tr><tr><td style="text-align:left;"><code>public void setOnShieldingAdd(Consumer&lt;Shielding&gt;)</code> / <code>setOnShieldingRemove(Runnable)</code> / <code>setShieldingGetter(Supplier&lt;@Nullable Shielding&gt;)</code></td><td style="text-align:left;">Binds callbacks to register, remove, and query the expanded list&#39;s occlusion shielding region, preventing mouse click-through between stacked dropdowns.</td></tr><tr><td style="text-align:left;"><code>public int calcMaxHeight()</code></td><td style="text-align:left;">Computes the maximum height of the expanded list within remaining bottom screen space (floored to a multiple of <code>getHeight()</code> to avoid clipped half-rows).</td></tr><tr><td style="text-align:left;"><code>public record DropdownEntry(Component desc, String id)</code></td><td style="text-align:left;">Dropdown entry data record. Provides <code>DropdownEntry.create(String id)</code> (using translation key <code>dropdown.anvillib_font.&lt;id&gt;</code>) and <code>DropdownEntry.create(String desc, String id)</code> (using <code>Component.literal(desc)</code>).</td></tr><tr><td style="text-align:left;"><code>public record Shielding(double x1, double y1, double x2, double y2, Dropdown dropdown)</code></td><td style="text-align:left;">Records the screen rectangle occupied by an expanded list. <code>isShielding(x, y, dropdown)</code> returns whether coordinates fall inside the shielding box for any other dropdown.</td></tr></tbody></table><h3 id="_3-anvillibfontdata-dev-anvilcraft-lib-v2-font-data-anvillibfontdata" tabindex="-1">3. <code>AnvilLibFontData</code> (<code>dev.anvilcraft.lib.v2.font.data.AnvilLibFontData</code>) <a class="header-anchor" href="#_3-anvillibfontdata-dev-anvilcraft-lib-v2-font-data-anvillibfontdata" aria-label="Permalink to &quot;3. `AnvilLibFontData` (`dev.anvilcraft.lib.v2.font.data.AnvilLibFontData`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Class / Method Signature</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public class AnvilLibFontData</code> / <code>public static class AnvilLibFontLanguageProvider extends LanguageProvider</code></td><td style="text-align:left;">Listens to <code>GatherDataEvent.Client</code> for <code>anvillib_font</code>, generating the 6 English translation keys for the config screen and dropdown narration (<code>screen.anvillib_font.config</code>, <code>screen.anvillib_font.config.family</code>, <code>screen.anvillib_font.config.font</code>, <code>screen.anvillib_font.config.test</code>, <code>narration.anvillib_font.dropdown.expanded</code>, <code>narration.anvillib_font.dropdown.collapsed</code>).</td></tr></tbody></table>',14))])}const w=d(s,[["render",g]]);export{y as __pageData,w as default};
